package com.operators;

public class LogicalOperators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//Logical AND
		System.out.println((5>3)&&(5>4));
		System.out.println((5<3)&&(5>4));
		System.out.println((5<3)&&(5<4));
		System.out.println((5>3)&&(5<4));
		
		//Logical OR
		System.out.println((5>3)||(5>4));
		System.out.println((5<3)||(5>4));
		System.out.println((5<3)||(5<4));
		System.out.println((5>3)||(5<4));
	}

}
